using namespace std;
 
struct Soal {
	string pertanyaan;
	string a, b, c, d, e;
	char benar;
};
 
void kerjakanSubtes(const string& namaSubtes, const vector<Soal>& daftarSoal) {
	cout << "\n=== " << namaSubtes << " ===\n";
 
	int skor = 0;
	char jawab;
 
	for (int i = 0; i < daftarSoal.size(); i++) {
    	const Soal &s = daftarSoal[i];
 
    	cout << "\nSoal " << i + 1 << ":\n";
    	cout << s.pertanyaan << "\n";
    	cout << "A. " << s.a << "\n";
    	cout << "B. " << s.b << "\n";
    	cout << "C. " << s.c << "\n";
    	cout << "D. " << s.d << "\n";
    	cout << "E. " << s.e << "\n";
 
    	cout << "Jawaban Anda (a/b/c/d/e): ";
    	cin >> jawab;
    	jawab = tolower(jawab);
 
    	if (jawab == s.benar) {
        	cout << "✔ Benar!\n";
        	skor++;
    	} else {
        	cout << "✘ Salah. Jawaban benar: " << (char)toupper(s.benar) << "\n";
    	}
	}
 
	cout << "\nSkor akhir: " << skor << " dari " << daftarSoal.size() << "\n";
}
 
